SELECT CAST(COUNT(CASE WHEN p.dod <= 7 THEN 1 END) AS FLOAT) / NULLIF(COUNT(CASE WHEN p.dod > 7 THEN 1 END), 0) AS mortality_ratio, (COUNT(CASE WHEN p.dod <= 7 THEN 1 END) - COUNT(CASE WHEN p.dod > 7 THEN 1 END)) AS absolute_difference, (COUNT(CASE WHEN p.dod <= 7 THEN 1 END)::FLOAT / NULLIF(COUNT(CASE WHEN p.dod > 7 THEN 1 END), 0)) AS relative_difference, MEDIAN(p.dod) AS median_death_time FROM patients p JOIN admissions a ON p.subject_id = a.subject_id WHERE p.gender = 'F' AND EXTRACT(YEAR FROM age(CURRENT_DATE, p.dob)) BETWEEN 50 AND 60 AND p.dod IS NOT NULL AND p.dod <= a.dischtime AND p.had_sepsis = TRUE AND p.shock_severity IS NULL;